package com.supportsphere.dao; import com.supportsphere.util.*; import java.sql.*; import java.util.*; public class NotificationDAO { public List<String> unread(int id)throws Exception{List<String>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT CONCAT(title,': ',message) FROM notifications WHERE user_id=? AND is_read=FALSE ORDER BY created_at DESC")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())x.add(r.getString(1));}}return x;} public int count(int id)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=FALSE")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}} public void markRead(int id)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE notifications SET is_read=TRUE WHERE user_id=?")){p.setInt(1,id);p.executeUpdate();}} }
